import numpy as np
open("est.py","w").write('''
import numpy as np
from scipy.stats import norm
G=np.load("G.npy")
q=(np.arange(8)+.5)/8
VAL={3:norm.ppf(q)+3}
xs=np.linspace(1e-6,1,200001); F=xs*(1-np.log(xs)); VAL[0]=np.interp(q,F,xs)
def groups(M):
    gr=[]
    for i in range(32):
        for g in gr:
            ok=True
            for j in g:
                sh=(M[i]>=0)&(M[j]>=0)
                if sh.sum()<8 or (M[i][sh]!=M[j][sh]).any(): ok=False;break
            if ok: g.append(i);break
        else: gr.append([i])
    return gr
def fill(M):
    A=M.copy()
    for g in groups(M):
        for b in range(32):
            v=M[g,b]; v=v[v>=0]
            if len(v): A[g,b]=v[0]
    for g in groups(M.T):
        for a in range(32):
            v=M[a,g]; v=v[v>=0]
            if len(v):
                for b in g:
                    if A[a,b]<0: A[a,b]=v[0]
    return A
def latents(s,M):
    A=fill(M); sc=np.full((32,32),np.nan); k=A>=0; sc[k]=VAL[s][A[k]]
    r=np.nanmean(sc,axis=1); c=np.nanmean(sc,axis=0)
    if s==3: u,v=r,c
    else: u,v=np.log(np.maximum(r,1e-3)),np.log(np.maximum(c,1e-3))
    P=np.add.outer(u,v); y=M[M>=0]; p=np.sort(P[M>=0]); cnt=np.bincount(y,minlength=8).cumsum()[:-1]
    th=np.array([(p[n-1]+p[n])/2 for n in cnt])
    return u,v,th,P,A
''')
